node_source='import https from "node:https";\n\nconst domain = "send.goldypov.com";\nconst key = process.env.RESEND_API_KEY;\nconst maximumBytes = 262144;\nlet finished = false;\nlet deadline;\nfunction emit(value) {\n  if (finished) return;\n  finished = true;\n  clearTimeout(deadline);\n  process.stdout.write(JSON.stringify(value) + "\\n");\n}\nif (!key) {\n  emit({ outcome: "KEY_NOT_PRESENT_IN_EXEC_ENVIRONMENT", providerRequestAttempted: false, httpStatus: null,\n    domain, domainFound: null, domainStatus: null, sendingCapability: null });\n} else {\n  const request = https.request({\n    hostname: "api.resend.com", port: 443, path: "/domains?limit=100", method: "GET",\n    rejectUnauthorized: true, maxHeaderSize: 16384,\n    headers: { Authorization: "Bearer " + key, Accept: "application/json", "User-Agent": "Tadazz-read-only-domain-readiness/1" },\n  }, (response) => {\n    const httpStatus = response.statusCode ?? null;\n    const base = { providerRequestAttempted: true, httpStatus, domain, domainFound: null, domainStatus: null, sendingCapability: null };\n    if (httpStatus !== 200) {\n      emit({ ...base, outcome: httpStatus === 403 ? "DOMAIN_METADATA_FORBIDDEN" :\n        httpStatus === 401 ? "PROVIDER_AUTHENTICATION_REJECTED" :\n        httpStatus && httpStatus >= 300 && httpStatus < 400 ? "REDIRECT_REFUSED" : "PROVIDER_HTTP_STATUS_NOT_200" });\n      response.destroy();\n      return;\n    }\n    if (!/^application\\/json(?:\\s*;|$)/iu.test(String(response.headers["content-type"] ?? ""))) {\n      emit({ ...base, outcome: "UNEXPECTED_METADATA_CONTENT_TYPE" });\n      response.destroy();\n      return;\n    }\n    let bytes = 0;\n    const chunks = [];\n    response.on("data", (chunk) => {\n      bytes += chunk.length;\n      if (bytes > maximumBytes) {\n        emit({ ...base, outcome: "METADATA_BODY_LIMIT" });\n        response.destroy();\n      } else chunks.push(chunk);\n    });\n    response.on("error", () => emit({ ...base, outcome: "METADATA_RESPONSE_FAILED" }));\n    response.on("end", () => {\n      if (finished) return;\n      let body;\n      try { body = JSON.parse(Buffer.concat(chunks).toString("utf8")); }\n      catch { emit({ ...base, outcome: "METADATA_JSON_INVALID" }); return; }\n      if (!body || !Array.isArray(body.data) || body.data.length > 100) {\n        emit({ ...base, outcome: "METADATA_SCHEMA_UNEXPECTED" });\n        return;\n      }\n      const matches = body.data.filter((row) => row && typeof row.name === "string" && row.name.toLowerCase() === domain);\n      if (matches.length !== 1) {\n        emit({ ...base, outcome: matches.length === 0 ? "DOMAIN_NOT_FOUND_IN_BOUNDED_PAGE" : "DUPLICATE_DOMAIN_METADATA",\n          domainFound: matches.length === 0 ? false : null });\n        return;\n      }\n      const row = matches[0];\n      const statuses = new Set(["not_started", "pending", "verified", "failed", "temporary_failure"]);\n      const capabilities = new Set(["enabled", "disabled"]);\n      emit({ ...base, outcome: "DOMAIN_METADATA_READ", domainFound: true,\n        domainStatus: statuses.has(row.status) ? row.status : "unrecognized",\n        sendingCapability: capabilities.has(row.capabilities?.sending) ? row.capabilities.sending : "not_reported" });\n    });\n  });\n  deadline = setTimeout(() => {\n    emit({ outcome: "PROVIDER_DEADLINE", providerRequestAttempted: true, httpStatus: null,\n      domain, domainFound: null, domainStatus: null, sendingCapability: null });\n    request.destroy();\n  }, 12000);\n  request.on("error", () => emit({ outcome: "PROVIDER_REQUEST_FAILED", providerRequestAttempted: true, httpStatus: null,\n    domain, domainFound: null, domainStatus: null, sendingCapability: null }));\n  request.end();\n}\n'
